{
  "items": [
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.mul",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  {φ ψ : MvPolynomial σ R} {m n : M} {w : σ → M},\n  MvPolynomial.IsWeightedHomogeneous w φ m →\n    MvPolynomial.IsWeightedHomogeneous w ψ n → MvPolynomial.IsWeightedHomogeneous w (φ * ψ) (m + n)"
    },
    {
      "name": "MvPolynomial.isWeightedHomogeneous_monomial",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] (w : σ → M)\n  (d : σ →₀ ℕ) (r : R) {m : M},\n  (Finsupp.weight w) d = m → MvPolynomial.IsWeightedHomogeneous w ((MvPolynomial.monomial d) r) m"
    },
    {
      "name": "MvPolynomial.isWeightedHomogeneous_zero_iff_weightedTotalDegree_eq_zero",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  [inst_2 : LinearOrder M] [inst_3 : OrderBot M] [CanonicallyOrderedAdd M] {w : σ → M} {p : MvPolynomial σ R},\n  MvPolynomial.IsWeightedHomogeneous w p 0 ↔ MvPolynomial.weightedTotalDegree w p = 0"
    },
    {
      "name": "MvPowerSeries.IsWeightedHomogeneous.mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {w : σ → ℕ} {f g : MvPowerSeries σ R} {p q : ℕ},\n  MvPowerSeries.IsWeightedHomogeneous w f p →\n    MvPowerSeries.IsWeightedHomogeneous w g q → MvPowerSeries.IsWeightedHomogeneous w (f * g) (p + q)"
    },
    {
      "name": "MvPolynomial.coeff_weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M] (d : σ →₀ ℕ),\n  MvPolynomial.coeff d ((MvPolynomial.weightedHomogeneousComponent w n) φ) =\n    if (Finsupp.weight w) d = n then MvPolynomial.coeff d φ else 0"
    },
    {
      "name": "MvPolynomial.sum_weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] (w : σ → M)\n  (φ : MvPolynomial σ R), ∑ᶠ (m : M), (MvPolynomial.weightedHomogeneousComponent w m) φ = φ"
    }
  ]
}
